'use client';
import React, { useState, useEffect, useMemo } from 'react';
import { useRouter } from 'next/navigation';
import { useMsal } from '@azure/msal-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { MultiSelect } from '@/components/ui/multi-select';
import {
    ArrowLeft, Download, RefreshCw, Edit2, RotateCcw,
    Search, Shield, ShieldCheck, Users, FileSpreadsheet, CheckCircle2
} from 'lucide-react';
import {
    ASSIGNMENTS_FILTERS_ENDPOINT,
    GROUPS_LIST_ENDPOINT,
    ROLE_SCOPETAGS_ENDPOINT,
    MIGRATION_BUILDER_SESSION_KEY,
} from '@/lib/constants';
import { useApiRequest } from '@/hooks/useApiRequest';
import { AssignmentFilter } from '@/types/assignmentFilter';

// ─── Types ───────────────────────────────────────────────────────────────────

interface SourceAssignment extends Record<string, unknown> {
    resourceType: string;
    subResourceType: string;
    assignmentType: string;
    platform: string | null;
    isAssigned: boolean;
    targetId: string | null;
    targetName: string;
    resourceId: string;
    resourceName: string | null;
    filterId: string | null;
    filterType: string;
    assignmentDirection: string;
    isExcluded: boolean;
    scopeTagIds?: string[];
}

interface GroupItem {
    id: string;
    displayName: string;
    description: string | null;
    membershipRule: string | null;
}

interface RoleScopeTag {
    id: string;
    displayName: string;
    isBuildIn: boolean;
}

type AssignmentAction = 'Add' | 'Remove' | 'NoAssignment' | 'Replace';
type FilterType = 'Include' | 'Exclude' | 'None';

interface EditableFields {
    groupName: string;
    groupId: string | null;
    assignmentAction: AssignmentAction;
    filterName: string | null;
    filterId: string | null;
    filterType: FilterType;
    scopeTagIds: string[];
}

interface BuilderRow extends EditableFields {
    id: string;
    policyName: string;
    resourceType: string;
    assignmentDirection: string;
    original: EditableFields;
    isModified: boolean;
}

// ─── Constants ────────────────────────────────────────────────────────────────

const SPECIAL_TARGETS = ['All Users', 'All Devices'];

// ─── Helpers ─────────────────────────────────────────────────────────────────

function normalizeFilterType(ft: string): FilterType {
    if (!ft || ft === 'None') return 'None';
    const l = ft.toLowerCase();
    if (l === 'include') return 'Include';
    if (l === 'exclude') return 'Exclude';
    return 'None';
}

function toBuilderRows(assignments: SourceAssignment[]): BuilderRow[] {
    return assignments.map((a, i) => {
        const filterType = normalizeFilterType(a.filterType);
        const base: EditableFields = {
            groupName: a.targetName || '',
            groupId: a.targetId || null,
            assignmentAction: a.targetName ? 'Add' : 'NoAssignment',
            filterName: null,     // resolved after filters load
            filterId: a.filterId && a.filterId !== 'None' ? a.filterId : null,
            filterType,
            scopeTagIds: a.scopeTagIds || [],
        };
        return {
            id: `row-${i}-${Date.now()}`,
            policyName: a.resourceName || '',
            resourceType: a.resourceType,
            assignmentDirection: a.assignmentDirection || 'Include',
            ...base,
            original: { ...base },
            isModified: false,
        };
    });
}

// ─── Page Component ───────────────────────────────────────────────────────────

export default function MigrationBuilderPage() {
    const router = useRouter();
    const { accounts } = useMsal();
    const { request } = useApiRequest();

    // Data state
    const [rows, setRows] = useState<BuilderRow[]>([]);
    const [groups, setGroups] = useState<GroupItem[]>([]);
    const [filters, setFilters] = useState<AssignmentFilter[]>([]);
    const [scopeTags, setScopeTags] = useState<RoleScopeTag[]>([]);
    const [loading, setLoading] = useState(false);
    const [dataLoaded, setDataLoaded] = useState(false);

    // Edit dialog
    const [editingRow, setEditingRow] = useState<BuilderRow | null>(null);
    const [editDialogOpen, setEditDialogOpen] = useState(false);
    const [groupSearch, setGroupSearch] = useState('');
    const [filterSearch, setFilterSearch] = useState('');

    // ── Load from sessionStorage ──────────────────────────────────────────────
    useEffect(() => {
        const stored = sessionStorage.getItem(MIGRATION_BUILDER_SESSION_KEY);
        if (stored) {
            try {
                const assignments: SourceAssignment[] = JSON.parse(stored);
                setRows(toBuilderRows(assignments));
            } catch (e) {
                console.error('Failed to parse stored assignments', e);
            }
        }
    }, []);

    // Resolve filter names once filters are loaded
    useEffect(() => {
        if (!filters.length || !rows.length) return;
        setRows(prev => prev.map(row => {
            if (!row.filterId) return row;
            const filter = filters.find(f => f.id === row.filterId);
            if (!filter || filter.displayName === row.filterName) return row;
            const name = filter.displayName;
            return {
                ...row,
                filterName: name,
                original: { ...row.original, filterName: name },
            };
        }));
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [filters]);

    // ── Fetch reference data ──────────────────────────────────────────────────
    const fetchReferenceData = async () => {
        if (!accounts.length) return;
        setLoading(true);
        try {
            const [groupRes, filterRes, tagRes] = await Promise.all([
                request<{ data: GroupItem[] }>(GROUPS_LIST_ENDPOINT, { method: 'GET' }),
                request<{ data: AssignmentFilter[] }>(ASSIGNMENTS_FILTERS_ENDPOINT, { method: 'GET' }),
                request<{ data: RoleScopeTag[] }>(ROLE_SCOPETAGS_ENDPOINT, { method: 'GET' }),
            ]);

            // ApiResponseWithCorrelation<{ data: Item[] }> → .data.data is the array
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const asArray = <T,>(res: any): T[] => {
                const inner = res?.data?.data;
                return Array.isArray(inner) ? (inner as T[]) : [];
            };

            setGroups(asArray<GroupItem>(groupRes));
            setFilters(asArray<AssignmentFilter>(filterRes));
            setScopeTags(asArray<RoleScopeTag>(tagRes));
            setDataLoaded(true);
        } finally {
            setLoading(false);
        }
    };

    // ── Memos ─────────────────────────────────────────────────────────────────
    const scopeTagOptions = useMemo(
        () => scopeTags.map(t => ({ label: t.displayName, value: t.id })),
        [scopeTags]
    );

    const filteredGroups = useMemo(() => {
        const q = groupSearch.toLowerCase().trim();
        if (!q) return groups.slice(0, 60);
        return groups.filter(g => g.displayName.toLowerCase().includes(q)).slice(0, 60);
    }, [groups, groupSearch]);

    const filteredFiltersSearch = useMemo(() => {
        const q = filterSearch.toLowerCase().trim();
        if (!q) return filters.slice(0, 60);
        return filters.filter(f => f.displayName.toLowerCase().includes(q)).slice(0, 60);
    }, [filters, filterSearch]);

    const modifiedCount = rows.filter(r => r.isModified).length;

    // ── Edit helpers ──────────────────────────────────────────────────────────
    const openEdit = (row: BuilderRow) => {
        setEditingRow({ ...row });
        setGroupSearch('');
        setFilterSearch('');
        setEditDialogOpen(true);
    };

    const saveEdit = () => {
        if (!editingRow) return;
        setRows(prev => prev.map(r => {
            if (r.id !== editingRow.id) return r;
            const isModified =
                editingRow.groupName !== r.original.groupName ||
                editingRow.assignmentAction !== r.original.assignmentAction ||
                editingRow.filterId !== r.original.filterId ||
                editingRow.filterType !== r.original.filterType ||
                JSON.stringify([...editingRow.scopeTagIds].sort()) !== JSON.stringify([...r.original.scopeTagIds].sort());
            return { ...editingRow, isModified };
        }));
        setEditDialogOpen(false);
        setEditingRow(null);
    };

    const resetRow = (rowId: string) => {
        setRows(prev => prev.map(r =>
            r.id !== rowId ? r : { ...r, ...r.original, isModified: false }
        ));
    };

    // ── Export ────────────────────────────────────────────────────────────────
    const exportCSV = () => {
        const resolveTagNames = (ids: string[]) =>
            ids.map(id => scopeTags.find(t => t.id === id)?.displayName || id).join(', ') || 'None';

        const header = 'PolicyName;GroupName;AssignmentDirection;AssignmentAction;Filter;Filter Type;Role Scope Tags';
        const csvRows = rows.map(r => [
            r.policyName,
            r.groupName,
            r.assignmentDirection,
            r.assignmentAction,
            r.filterName || '',
            r.filterType === 'None' ? '' : r.filterType,
            resolveTagNames(r.scopeTagIds),
        ].join(';'));

        const content = [header, ...csvRows].join('\n');
        const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'assignment-migration.csv';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    // ── Render helpers ────────────────────────────────────────────────────────
    const resolvedScopeTagNames = (ids: string[]) =>
        ids.map(id => scopeTags.find(t => t.id === id)?.displayName || id).join(', ') || 'None';

    const actionBadgeVariant = (action: AssignmentAction) => {
        if (action === 'Add' || action === 'Replace') return 'default';
        if (action === 'Remove') return 'destructive';
        return 'secondary';
    };

    // ─────────────────────────────────────────────────────────────────────────
    return (
        <div className="p-4 lg:p-8 space-y-6 w-full max-w-none">
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
                <div>
                    <Button variant="ghost" size="sm" className="mb-2 -ml-2" onClick={() => router.back()}>
                        <ArrowLeft className="h-4 w-4 mr-1" /> Back
                    </Button>
                    <h1 className="text-2xl lg:text-3xl font-bold text-gray-600 dark:text-white">
                        Assignment Migration Builder
                    </h1>
                    <p className="text-gray-600 dark:text-gray-300 mt-1 text-sm">
                        Modify group targets, actions, filters and scope tags — then export to a migration CSV.
                    </p>
                </div>
                <div className="flex gap-2 flex-wrap shrink-0">
                    <Button onClick={fetchReferenceData} variant="outline" size="sm" disabled={loading}>
                        <RefreshCw className={`h-4 w-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
                        {dataLoaded ? 'Refresh Data' : 'Load Reference Data'}
                    </Button>
                    {dataLoaded && (
                        <Badge variant="outline" className="h-8 px-3 flex items-center gap-1 text-green-600 border-green-400">
                            <CheckCircle2 className="h-3 w-3" />
                            {groups.length} groups · {filters.length} filters · {scopeTags.length} tags
                        </Badge>
                    )}
                    <Button onClick={exportCSV} size="sm" disabled={rows.length === 0}>
                        <Download className="h-4 w-4 mr-2" />
                        Export CSV
                    </Button>
                    <Button variant="outline" size="sm" onClick={() => router.push('/deployment/assignments')}>
                        <FileSpreadsheet className="h-4 w-4 mr-2" />
                        Go to Deployment
                    </Button>
                </div>
            </div>

            {/* Status badges */}
            {rows.length > 0 && (
                <div className="flex gap-2 flex-wrap items-center">
                    <Badge variant="secondary">{rows.length} assignments loaded</Badge>
                    {modifiedCount > 0 && (
                        <Badge className="bg-yellow-500 hover:bg-yellow-600">{modifiedCount} modified</Badge>
                    )}
                    {!dataLoaded && (
                        <Badge variant="outline" className="text-orange-500 border-orange-400">
                            ⚠ Load reference data to enable editing
                        </Badge>
                    )}
                </div>
            )}

            {/* Empty state */}
            {rows.length === 0 && (
                <Card className="bg-white/60 dark:bg-gray-900/30 backdrop-blur-lg border border-white/30 dark:border-white/10">
                    <CardContent className="py-16 text-center">
                        <Users className="h-16 w-16 mx-auto text-gray-400 mb-4" />
                        <h3 className="text-xl font-medium text-gray-900 dark:text-white mb-2">
                            No assignments loaded
                        </h3>
                        <p className="text-gray-500 dark:text-gray-400 mb-6 max-w-md mx-auto text-sm">
                            Go to the Assignments Overview page, apply your filters, then click{' '}
                            <strong>&quot;Open in Migration Builder&quot;</strong> to load assignments here.
                        </p>
                        <Button onClick={() => router.push('/assistant/assignments-overview')}>
                            <ArrowLeft className="h-4 w-4 mr-2" />
                            Go to Assignments Overview
                        </Button>
                    </CardContent>
                </Card>
            )}

            {/* Table */}
            {rows.length > 0 && (
                <Card className="bg-white/60 dark:bg-gray-900/30 backdrop-blur-lg border border-white/30 dark:border-white/10 overflow-hidden">
                    <CardHeader className="pb-2 border-b">
                        <CardTitle className="text-sm font-medium text-gray-600 dark:text-gray-300">
                            Assignments ({rows.length})
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="p-0">
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm">
                                <thead>
                                    <tr className="border-b bg-muted/40">
                                        <th className="px-3 py-3 text-left font-medium text-xs w-6" />
                                        <th className="px-3 py-3 text-left font-medium text-xs min-w-[220px]">Policy</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs min-w-[140px]">Group</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs w-[90px]">Direction</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs w-[100px]">Action</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs min-w-[130px]">Filter</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs w-[90px]">Filter Type</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs min-w-[140px]">Scope Tags</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs w-[80px]">Edit</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {rows.map((row, idx) => (
                                        <tr
                                            key={row.id}
                                            className={[
                                                'border-b transition-colors',
                                                row.isModified
                                                    ? 'bg-yellow-50/40 dark:bg-yellow-900/10'
                                                    : idx % 2 === 0 ? '' : 'bg-muted/10',
                                                'hover:bg-muted/30',
                                            ].join(' ')}
                                        >
                                            {/* Modified indicator */}
                                            <td className="px-3 py-2">
                                                {row.isModified && (
                                                    <div className="h-2 w-2 rounded-full bg-yellow-500 mx-auto" title="Modified" />
                                                )}
                                            </td>

                                            {/* Policy */}
                                            <td className="px-3 py-2">
                                                <div className="font-medium truncate max-w-[280px] text-xs" title={row.policyName}>
                                                    {row.policyName || <span className="text-muted-foreground italic">—</span>}
                                                </div>
                                                <div className="text-[10px] text-muted-foreground">{row.resourceType}</div>
                                            </td>

                                            {/* Group */}
                                            <td className="px-3 py-2">
                                                <span className="truncate block max-w-[180px] text-xs" title={row.groupName}>
                                                    {row.groupName || <span className="text-muted-foreground italic">None</span>}
                                                </span>
                                            </td>

                                            {/* Direction */}
                                            <td className="px-3 py-2">
                                                <Badge
                                                    variant={row.assignmentDirection === 'Exclude' ? 'destructive' : 'default'}
                                                    className="text-[10px] py-0 px-1.5"
                                                >
                                                    {row.assignmentDirection}
                                                </Badge>
                                            </td>

                                            {/* Action */}
                                            <td className="px-3 py-2">
                                                <Badge
                                                    variant={actionBadgeVariant(row.assignmentAction)}
                                                    className="text-[10px] py-0 px-1.5"
                                                >
                                                    {row.assignmentAction}
                                                </Badge>
                                            </td>

                                            {/* Filter */}
                                            <td className="px-3 py-2">
                                                <span className="truncate block max-w-[160px] text-xs" title={row.filterName || ''}>
                                                    {row.filterName || <span className="text-muted-foreground text-[10px]">None</span>}
                                                </span>
                                            </td>

                                            {/* Filter Type */}
                                            <td className="px-3 py-2">
                                                {row.filterType !== 'None' && row.filterName ? (
                                                    <Badge
                                                        variant={row.filterType === 'Include' ? 'default' : 'destructive'}
                                                        className="text-[10px] py-0 px-1.5"
                                                    >
                                                        {row.filterType === 'Include'
                                                            ? <Shield className="h-2 w-2 mr-0.5 inline" />
                                                            : <ShieldCheck className="h-2 w-2 mr-0.5 inline" />}
                                                        {row.filterType}
                                                    </Badge>
                                                ) : (
                                                    <span className="text-muted-foreground text-[10px]">None</span>
                                                )}
                                            </td>

                                            {/* Scope Tags */}
                                            <td className="px-3 py-2 text-[10px] text-muted-foreground max-w-[160px] truncate">
                                                {row.scopeTagIds.length > 0
                                                    ? resolvedScopeTagNames(row.scopeTagIds)
                                                    : 'None'}
                                            </td>

                                            {/* Actions */}
                                            <td className="px-3 py-2">
                                                <div className="flex gap-1">
                                                    <Button
                                                        size="sm"
                                                        variant="outline"
                                                        className="h-6 px-2"
                                                        onClick={() => openEdit(row)}
                                                        disabled={!dataLoaded}
                                                        title={dataLoaded ? 'Edit row' : 'Load reference data first'}
                                                    >
                                                        <Edit2 className="h-3 w-3" />
                                                    </Button>
                                                    {row.isModified && (
                                                        <Button
                                                            size="sm"
                                                            variant="ghost"
                                                            className="h-6 px-2 text-muted-foreground"
                                                            onClick={() => resetRow(row.id)}
                                                            title="Reset to original"
                                                        >
                                                            <RotateCcw className="h-3 w-3" />
                                                        </Button>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </CardContent>
                </Card>
            )}

            {/* ── Edit Dialog ───────────────────────────────────────────────── */}
            <Dialog open={editDialogOpen} onOpenChange={open => { if (!open) setEditDialogOpen(false); }}>
                <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle className="text-base">Edit Assignment</DialogTitle>
                        {editingRow && (
                            <p className="text-xs text-muted-foreground truncate pt-1">{editingRow.policyName}</p>
                        )}
                    </DialogHeader>

                    {editingRow && (
                        <div className="space-y-5 pt-1">

                            {/* Group / Target Name */}
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Group (Target Name)</Label>
                                <div className="relative">
                                    <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
                                    <Input
                                        className="pl-8 h-8 text-sm"
                                        placeholder="Search groups…"
                                        value={groupSearch}
                                        onChange={e => setGroupSearch(e.target.value)}
                                    />
                                </div>

                                <div className="border rounded-md max-h-44 overflow-y-auto divide-y text-sm">
                                    {/* Manual / as-is entry */}
                                    {groupSearch.trim() && (
                                        <button
                                            className="w-full text-left px-3 py-2 hover:bg-muted text-xs"
                                            onClick={() => setEditingRow(prev => prev
                                                ? { ...prev, groupName: groupSearch.trim(), groupId: null }
                                                : null)}
                                        >
                                            Use &quot;<strong>{groupSearch.trim()}</strong>&quot; as-is
                                        </button>
                                    )}

                                    {/* Special targets */}
                                    {SPECIAL_TARGETS
                                        .filter(s => !groupSearch.trim() || s.toLowerCase().includes(groupSearch.toLowerCase()))
                                        .map(special => (
                                            <button
                                                key={special}
                                                className={`w-full text-left px-3 py-2 text-xs hover:bg-muted ${editingRow.groupName === special && !editingRow.groupId ? 'bg-muted font-semibold' : ''}`}
                                                onClick={() => setEditingRow(prev => prev ? { ...prev, groupName: special, groupId: null } : null)}
                                            >
                                                {special}
                                            </button>
                                        ))}

                                    {/* API groups */}
                                    {filteredGroups.length === 0 && !groupSearch.trim() && (
                                        <p className="text-xs text-muted-foreground px-3 py-2">Type to search groups…</p>
                                    )}
                                    {filteredGroups.map(g => (
                                        <button
                                            key={g.id}
                                            className={`w-full text-left px-3 py-2 text-xs hover:bg-muted ${editingRow.groupId === g.id ? 'bg-muted font-semibold' : ''}`}
                                            onClick={() => setEditingRow(prev => prev ? { ...prev, groupName: g.displayName, groupId: g.id } : null)}
                                        >
                                            <div>{g.displayName}</div>
                                            {g.membershipRule && (
                                                <div className="text-[10px] text-purple-500">Dynamic group</div>
                                            )}
                                        </button>
                                    ))}
                                </div>

                                {editingRow.groupName && (
                                    <p className="text-[11px] text-muted-foreground">
                                        Selected: <strong>{editingRow.groupName}</strong>
                                    </p>
                                )}
                            </div>

                            {/* Assignment Action */}
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Assignment Action</Label>
                                <Select
                                    value={editingRow.assignmentAction}
                                    onValueChange={v => setEditingRow(prev => prev
                                        ? { ...prev, assignmentAction: v as AssignmentAction }
                                        : null)}
                                >
                                    <SelectTrigger className="h-8 text-sm">
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="Add">Add</SelectItem>
                                        <SelectItem value="Remove">Remove</SelectItem>
                                        <SelectItem value="Replace">Replace</SelectItem>
                                        <SelectItem value="NoAssignment">NoAssignment</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>

                            {/* Filter */}
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Filter</Label>
                                <div className="relative">
                                    <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
                                    <Input
                                        className="pl-8 h-8 text-sm"
                                        placeholder="Search filters…"
                                        value={filterSearch}
                                        onChange={e => setFilterSearch(e.target.value)}
                                    />
                                </div>
                                <div className="border rounded-md max-h-40 overflow-y-auto divide-y text-sm">
                                    <button
                                        className={`w-full text-left px-3 py-2 text-xs hover:bg-muted ${!editingRow.filterId ? 'bg-muted font-semibold' : ''}`}
                                        onClick={() => setEditingRow(prev => prev
                                            ? { ...prev, filterId: null, filterName: null, filterType: 'None' }
                                            : null)}
                                    >
                                        <span className="text-muted-foreground">— No Filter —</span>
                                    </button>
                                    {filteredFiltersSearch.length === 0 && (
                                        <p className="text-xs text-muted-foreground px-3 py-2">No filters found</p>
                                    )}
                                    {filteredFiltersSearch.map(f => (
                                        <button
                                            key={f.id}
                                            className={`w-full text-left px-3 py-2 text-xs hover:bg-muted ${editingRow.filterId === f.id ? 'bg-muted font-semibold' : ''}`}
                                            onClick={() => setEditingRow(prev => prev
                                                ? {
                                                    ...prev,
                                                    filterId: f.id,
                                                    filterName: f.displayName,
                                                    filterType: prev.filterType === 'None' ? 'Include' : prev.filterType,
                                                }
                                                : null)}
                                        >
                                            <div>{f.displayName}</div>
                                            <div className="text-[10px] text-muted-foreground">{f.platform} · {f.assignmentFilterManagementType}</div>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Filter Type */}
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Filter Type</Label>
                                <Select
                                    value={editingRow.filterType}
                                    disabled={!editingRow.filterId}
                                    onValueChange={v => setEditingRow(prev => prev
                                        ? { ...prev, filterType: v as FilterType }
                                        : null)}
                                >
                                    <SelectTrigger className="h-8 text-sm" disabled={!editingRow.filterId}>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="Include">Include</SelectItem>
                                        <SelectItem value="Exclude">Exclude</SelectItem>
                                        <SelectItem value="None">None</SelectItem>
                                    </SelectContent>
                                </Select>
                                {!editingRow.filterId && (
                                    <p className="text-[11px] text-muted-foreground">Select a filter first</p>
                                )}
                            </div>

                            {/* Scope Tags */}
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Scope Tags</Label>
                                <MultiSelect
                                    options={scopeTagOptions}
                                    selected={editingRow.scopeTagIds}
                                    onChange={ids => setEditingRow(prev => prev ? { ...prev, scopeTagIds: ids } : null)}
                                    placeholder="Select scope tags…"
                                />
                            </div>

                            {/* Dialog actions */}
                            <div className="flex justify-between items-center pt-2 border-t">
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    className="text-muted-foreground"
                                    onClick={() => {
                                        // Reset editing row to original
                                        setEditingRow(prev => prev
                                            ? { ...prev, ...prev.original }
                                            : null);
                                    }}
                                >
                                    <RotateCcw className="h-3.5 w-3.5 mr-1" />
                                    Reset to Original
                                </Button>
                                <div className="flex gap-2">
                                    <Button variant="outline" size="sm" onClick={() => setEditDialogOpen(false)}>
                                        Cancel
                                    </Button>
                                    <Button size="sm" onClick={saveEdit}>
                                        Save Changes
                                    </Button>
                                </div>
                            </div>
                        </div>
                    )}
                </DialogContent>
            </Dialog>
        </div>
    );
}

